	@Test
	void constantPredicateAliasesRetainIndependentCountChannelsAndGrouping() {
		set("rdf4j.lmdb.directAdjacency.scanAggregates.enabled", "true");
		set("rdf4j.lmdb.prefixRun.enabled", "true");
		String predicate = "<" + EX + "p>";
		for (String group : List.of("", "s")) {
			for (String channels : List.of("(COUNT(*) AS ?count)", "(COUNT(?p) AS ?count)",
					"(COUNT(DISTINCT ?p) AS ?count)",
					"(COUNT(DISTINCT ?s) AS ?count) (COUNT(DISTINCT ?o) AS ?other)",
					"(COUNT(*) AS ?count) (COUNT(?s) AS ?subjects) (COUNT(?p) AS ?predicates) "
							+ "(COUNT(?o) AS ?objects) (COUNT(DISTINCT ?s) AS ?distinctSubjects) "
							+ "(COUNT(DISTINCT ?p) AS ?distinctPredicates) (COUNT(DISTINCT ?o) AS ?distinctObjects)")) {
				String query = "SELECT " + (group.isEmpty() ? "" : "?" + group + " ") + channels
						+ " WHERE { ?s " + predicate + " ?o . BIND(" + predicate + " AS ?p) }"
						+ (group.isEmpty() ? "" : " GROUP BY ?" + group);
				List<BindingSet> generic;
				set("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
				try {
					generic = rows(query, null);
				} finally {
					set("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
				}
				assertThat(generic).as("the real base source must admit the complete relation").isNotEmpty();
				assertThat(rows(query, null)).as("AUTO semantic parity:%n%s", query)
						.containsExactlyInAnyOrderElementsOf(generic);
				GenericPlanNode plan = explain(query, null, Explanation.Level.Optimized);
				assertThat(eligible(plan)).as("actual native reducer admission:%n%s", plan)
						.contains(LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE);
				List<BindingSet> actual = assertDoesNotThrow(
						() -> rows(query, LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE),
						"the admitted constant-alias reducer must open:\n" + query + "\n" + plan);
				assertThat(actual).containsExactlyInAnyOrderElementsOf(generic);
			}
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
			LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED })
	void effectfulAggregateReportsItsSerialValueAuthorityAtExecution(String strategy) {
		GenericPlanNode telemetry = explain(EFFECTFUL_QUERY, strategy, Explanation.Level.Telemetry);
		String path = findMetric(telemetry, LmdbNativeExplain.EXECUTION_PATH);
		assertThat(path)
				.as("RAND is an effectful value producer and cannot use the wildcard aggregate route")
				.isEqualTo(strategy)
				.doesNotContain("Wildcard")
				.doesNotContain("Parallel");
		assertThat(findLongMetric(telemetry, "nativeIrBindEvaluationsActual"))
				.as("the RAND BIND must be evaluated once for each of the 32 source rows")
				.isEqualTo(32L);
		Long parallelWorkers = findLongMetric(telemetry, "nativeIrParallelWorkersStartedActual");
		if (parallelWorkers != null) {
			assertThat(parallelWorkers)
					.as("the effectful serial route must not engage parallel workers")
					.isEqualTo(0L);
		}
		GenericPlanNode optimized = explain(EFFECTFUL_QUERY, null, Explanation.Level.Optimized);
		assertThat(optimized.toString())
				.contains("Computed values, full-row DISTINCT or encounter order require one serial value authority");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void effectfulAggregateEvaluatesEachInputOnceForAutoAndNestedLoop(boolean forceNestedLoop) {
		String functionUri = "urn:rdf4j:test:aggregate-explain-volatile";
		AtomicInteger calls = new AtomicInteger();
		Function function = new Function() {
			@Override
			public String getURI() {
				return functionUri;
			}

			@Override
			public Determinism getDeterminism() {
				return Determinism.VOLATILE;
			}

			@Override
			public Value evaluate(ValueFactory valueFactory, Value... args) {
				return valueFactory.createLiteral(calls.incrementAndGet());
			}
		};
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.get(functionUri).orElse(null);
		registry.add(function);
		try {
			String query = "SELECT (COUNT(?r) AS ?count) WHERE { ?s ?p ?o . BIND(<" + functionUri
					+ ">() AS ?r) }";
			String strategy = forceNestedLoop ? LmdbNativeAttemptMetrics.PATH_NESTED_LOOP : null;
			List<BindingSet> result = rows(query, strategy);
			assertThat(result).hasSize(1);
			assertThat(result.getFirst().getValue("count").stringValue()).isEqualTo("32");
			assertThat(calls.get()).as("one volatile evaluation per result input").isEqualTo(32);

			calls.set(0);
			GenericPlanNode telemetry = explain(query, strategy, Explanation.Level.Telemetry);
			assertThat(calls.get()).as("one volatile evaluation per telemetry input").isEqualTo(32);
			assertThat(findMetric(telemetry, LmdbNativeExplain.EXECUTION_PATH))
					.as("an effectful aggregate must retain a serial execution route")
					.isNotNull()
					.doesNotContain("Wildcard")
					.doesNotContain("Parallel");
			Long parallelWorkers = findLongMetric(telemetry, "nativeIrParallelWorkersStartedActual");
			if (parallelWorkers != null) {
				assertThat(parallelWorkers).as("the effectful route must not engage parallel workers").isEqualTo(0L);
			}
			String decision = findMetric(telemetry, LmdbNativeExplain.ADAPTIVE_COST_DECISION);
			if (decision != null) {
				String winner = decision.split(";", 2)[0];
				assertThat(winner).startsWith("winner=").doesNotContain("Wildcard").doesNotContain("Parallel");
			}
			if (forceNestedLoop) {
				assertThat(decision)
						.as("the forced nested-loop strategy must actually win")
						.contains("winner=nestedLoop");
			}
		} finally {
			registry.remove(function);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	@Test
	void serialValueAuthorityKeepsEveryLegalIrTierAndItsExactFallbackInTheInventory() {
		List<String> candidates = eligible(explain(EFFECTFUL_QUERY, null, Explanation.Level.Optimized));
		assertThat(candidates).as("one serial authority restricts ownership, not legal execution tiers")
				.contains(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
						LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED,
						LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
		assertThat(candidates).noneMatch(tag -> tag.contains("Parallel"));
	}

